mapper.select:
SELECT o.order_no, o.order_status, o.payment_status, o.pay_amount, o.created_at, COALESCE(SUM(oi.quantity), 0) AS total_quantity, ( SELECT oi2.sku_image FROM order_item oi2 WHERE oi2.order_id = o.id LIMIT 1 ) AS product_image, ( SELECT oi2.product_name FROM order_item oi2 WHERE oi2.order_id = o.id LIMIT 1 ) AS product_name FROM `order` o LEFT JOIN order_item oi ON oi.order_id = o.id WHERE o.user_id = #{userId} AND o.deleted = 0
AND o.order_status = #{orderStatus}
GROUP BY o.id ORDER BY MAX(o.created_at) DESC

SELECT o.order_no, o.user_id, o.receiver_name, o.receiver_phone, o.order_status, o.payment_status, o.pay_amount, o.created_at, COALESCE(SUM(oi.quantity), 0) AS item_count FROM `order` o LEFT JOIN order_item oi ON oi.order_id = o.id LEFT JOIN `user` u ON u.id = o.user_id WHERE o.deleted = 0
AND o.order_no = #{orderNo}
AND u.phone = #{userPhone}
AND o.order_status = #{orderStatus}
AND o.payment_status = #{paymentStatus}
AND o.created_at >= #{startTime}
AND o.created_at <= #{endTime}
GROUP BY o.id, o.order_no, o.user_id, o.receiver_name, o.receiver_phone, o.order_status, o.payment_status, o.pay_amount, o.created_at ORDER BY o.created_at DESC

SELECT *
FROM `order`
WHERE order_status = 0
  AND deleted = 0
  AND created_at < #{deadline}
LIMIT #{limit}
